-- Change 'l0001_teach_hints': Lesson 1 teach texts become hint lines under the Sounds like cell; new title
-- Generated by approved-scripts/db_sql.py change from data/*.csv. Upserts change only rows that differ,
-- including rows lessons use. Rows: 1 lessons, 3 units, 4 lesson_items.
-- IDs: L0001 units:C01 units:C13f units:V04

insert into public.lessons as t (lesson_id, lesson_order, title_en, kind, summary_en, source, confidence, notes) values
  ('L0001', 1, 'First letters: ກ ◌ິ ◌ນ', 'letters', 'Three letters and a word you can read with them.', 'SRC-AGENT:lesson', 'unverified', 'Lesson 1 is fixed by the user: ກິນ (W000018). Title and summary shortened 2026-10-24 so they do not give the word away; the title is not shown on the cards.')
on conflict (lesson_id) do update set lesson_order = excluded.lesson_order, title_en = excluded.title_en, kind = excluded.kind, summary_en = excluded.summary_en, source = excluded.source, confidence = excluded.confidence, notes = excluded.notes, retired_at = null
where (t.retired_at is not null or (t.lesson_order, t.title_en, t.kind, t.summary_en, t.source, t.confidence, t.notes) is distinct from (excluded.lesson_order, excluded.title_en, excluded.kind, excluded.summary_en, excluded.source, excluded.confidence, excluded.notes));
insert into public.units as t (unit_id, kind, role, base_id, lao, teach_en, intro_lesson_id, source, confidence, notes) values
  ('C01', 'consonant', 'initial', 'C01', 'ກ', 'A hard g, as in the word ''get''.', 'L0001', 'SRC-AGENT:lesson', 'unverified', 'From letters.csv C01 pron_tip (verified); wording by agent. Shortened 2026-10-24 (teach cards: one line on the front).'),
  ('C13f', 'consonant', 'final', 'C13', '◌ນ', 'At the end of a syllable, as in the word ''sun''.', 'L0001', 'SRC-AGENT:lesson', 'unverified', 'From letters.csv C13 (ipa_final n; verified); wording by agent. Shortened 2026-10-24.'),
  ('V04', 'vowel', 'vowel', 'V04', '◌ິ', 'As in the word ''bit''. Written above the consonant, but said after it.', 'L0001', 'SRC-AGENT:lesson', 'unverified', 'From vowels.csv V04 pron_tip (verified); wording by agent. Shortened 2026-10-24.')
on conflict (unit_id) do update set kind = excluded.kind, role = excluded.role, base_id = excluded.base_id, lao = excluded.lao, teach_en = excluded.teach_en, intro_lesson_id = excluded.intro_lesson_id, source = excluded.source, confidence = excluded.confidence, notes = excluded.notes, retired_at = null
where (t.retired_at is not null or (t.kind, t.role, t.base_id, t.lao, t.teach_en, t.intro_lesson_id, t.source, t.confidence, t.notes) is distinct from (excluded.kind, excluded.role, excluded.base_id, excluded.lao, excluded.teach_en, excluded.intro_lesson_id, excluded.source, excluded.confidence, excluded.notes));
insert into public.lesson_items as t (lesson_id, position, item_type, item_id, role, notes) values
  ('L0001', 1, 'unit', 'C01', 'new', 'initial ກ'),
  ('L0001', 2, 'unit', 'V04', 'new', 'short vowel written above the consonant'),
  ('L0001', 3, 'unit', 'C13f', 'new', 'final ນ'),
  ('L0001', 4, 'word', 'W000018', 'new', 'first word; show both common senses (eat and drink) per user 2026-10-24')
on conflict (lesson_id, position) do update set item_type = excluded.item_type, item_id = excluded.item_id, role = excluded.role, notes = excluded.notes, retired_at = null
where (t.retired_at is not null or (t.item_type, t.item_id, t.role, t.notes) is distinct from (excluded.item_type, excluded.item_id, excluded.role, excluded.notes));
update public.lesson_items t set retired_at = now()
where t.retired_at is null and t.lesson_id in ('L0001') and (t.lesson_id, t.position) not in (('L0001', 1), ('L0001', 2), ('L0001', 3), ('L0001', 4));
